mapper.select:
select * from con_contract c
c.contract_status = 'INCEPT' and c.deposit_deduct_method = 'AUTO' and exists (select 1 from csh_transaction t where t.contract_id = c.contract_id AND t.transaction_type = 'DEPOSIT' AND t.reversed_flag = 'N' ) and nvl((select nvl(sum(ct2.transaction_amount), 0) - nvl(sum(nvl(ct2.WRITE_OFF_AMOUNT,0)), 0) from csh_transaction ct2 where ct2.contract_id = c.contract_id and ct2.BUSINESS_TYPE='DEPOSIT'),0) > 0 and nvl((select nvl(sum(cc.due_amount),0) - nvl(sum(nvl(cc.received_amount,0)),0) from con_contract_cashflow cc where cc.contract_id = c.contract_id and cc.times=c.LEASE_TIMES and cc.cf_item in (1,8,9,11,13)),0) > 0
and c.contract_number = #{contractNumber}
